// Rango del mes anterior (el informe del dia 1 habla del mes que acaba de pasar).
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

const [anio, mes] = hoy.split('-').map(Number);
const primero = new Date(Date.UTC(anio, mes - 2, 1));
const ultimo = new Date(Date.UTC(anio, mes - 1, 0));

const iso = (d) => d.toISOString().slice(0, 10);
const desde = iso(primero);
const hasta = iso(ultimo);
const nombre = primero.toLocaleDateString('es-ES', { month: 'long', year: 'numeric', timeZone: 'UTC' });

return [{ json: { desde, hasta, mes: nombre } }];

// Calcula el informe del mes (HU-08).
//
// - Recaudacion: ventas directas y abonos por separado (los abonos iniciales
//   cuentan en el mes en que se crearon).
// - Pendiente de cobro: suma de lo que falta de los apartados activos.
// - Apartados nuevos, liquidados y vencidos del mes.
//
// Ninguna cifra se inventa: todas salen de la API y aqui solo se suman.
const rango = $('Rango del mes').first().json ?? {};
const desde = rango.desde;
const hasta = rango.hasta;

const ventas = $('Ventas del mes').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((v) => v && v.id !== undefined);
const abonos = $('Abonos del mes').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((a) => a && a.id !== undefined);
const apartados = $('Apartados').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((a) => a && a.id !== undefined);
const vales = $('Vales').all().flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json])).filter((v) => v && v.id !== undefined);

const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const dentro = (fecha) => String(fecha ?? '') >= desde && String(fecha ?? '') <= hasta;

const ventasDirectas = redondear(ventas.reduce((s, v) => s + Number(v.importe ?? 0), 0));
const totalAbonos = redondear(abonos.reduce((s, a) => s + Number(a.importe ?? 0), 0));

const pendientes = apartados.filter((a) => String(a.estado) === 'activo');
const pendienteTotal = redondear(pendientes.reduce((s, a) => s + Number(a.pendiente ?? 0), 0));

const porEstado = { activo: 0, liquidado: 0, vencido: 0 };
for (const a of apartados) {
  if (porEstado[a.estado] !== undefined) porEstado[a.estado] += 1;
}

// Un apartado ha tenido movimiento en el mes si tiene algun abono dentro del mes.
const conMovimiento = new Set(abonos.map((a) => a.apartado_id));
const nuevos = apartados.filter((a) => dentro(a.fecha));
const liquidados = apartados.filter((a) => String(a.estado) === 'liquidado' && conMovimiento.has(a.id));
const vencidos = vales.filter((v) => dentro(v.fecha));

return [{
  json: {
    desde,
    hasta,
    mes: rango.mes,
    ventas_directas: ventasDirectas,
    abonos: totalAbonos,
    recaudacion: redondear(ventasDirectas + totalAbonos),
    pendiente_cobro: pendienteTotal,
    apartados_nuevos: nuevos.length,
    apartados_liquidados: liquidados.length,
    apartados_vencidos: vencidos.length,
    por_estado: porEstado,
    num_ventas: ventas.length,
    num_abonos: abonos.length,
    detalle_liquidados: liquidados.map((a) => ({ id: a.id, cliente: a.cliente, producto: a.producto, precio: a.precio })),
    detalle_vencidos: vencidos.map((v) => ({ codigo: v.codigo, importe: v.importe, apartado_id: v.apartado_id })),
  },
}];

// Monta el informe mensual para Marisa.
// La API da las fechas como AAAA-MM-DD; en los mensajes van como dia/mes/año.
const fechaES = (f) => {
  const t = String(f ?? '').split('-');
  return t.length === 3 ? t[2].slice(0, 2) + '/' + t[1] + '/' + t[0] : String(f ?? '');
};
const i = $input.first().json ?? {};
// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cuerpo = [
  'Informe de ' + (i.mes ?? '') + ' (' + fechaES(i.desde) + ' a ' + fechaES(i.hasta) + ')',
  '',
  'RECAUDACION',
  '  Ventas directas: ' + euros(i.ventas_directas) + ' (' + (i.num_ventas ?? 0) + ' ventas)',
  '  Abonos de apartados: ' + euros(i.abonos) + ' (' + (i.num_abonos ?? 0) + ' abonos)',
  '  Total recaudado: ' + euros(i.recaudacion),
  '',
  'PENDIENTE DE COBRO',
  '  Total por cobrar: ' + euros(i.pendiente_cobro),
  '  Apartados activos: ' + ((i.por_estado ?? {}).activo ?? 0),
  '',
  'APARTADOS DEL MES',
  '  Nuevos: ' + (i.apartados_nuevos ?? 0),
  '  Liquidados: ' + (i.apartados_liquidados ?? 0),
  '  Vencidos: ' + (i.apartados_vencidos ?? 0),
  '',
  'Un saludo,',
  'Zapateria Paso Firme',
].join('\n');

const tabla = '<table border="1" cellpadding="6" cellspacing="0">'
  + '<tr><th>Concepto</th><th>Importe</th></tr>'
  + '<tr><td>Ventas directas</td><td>' + euros(i.ventas_directas) + '</td></tr>'
  + '<tr><td>Abonos de apartados</td><td>' + euros(i.abonos) + '</td></tr>'
  + '<tr><td><strong>Total recaudado</strong></td><td><strong>' + euros(i.recaudacion) + '</strong></td></tr>'
  + '<tr><td>Pendiente de cobro</td><td>' + euros(i.pendiente_cobro) + '</td></tr>'
  + '</table>';

return [{
  json: {
    canal: 'email',
    email: emailTienda,
    asunto: 'Informe mensual · ' + (i.mes ?? ''),
    cuerpo,
    cuerpo_html: '<p>' + escapar(cuerpo).replace(/\n/g, '<br>') + '</p>' + tabla,
  },
}];

// Devuelve UN solo item con el rango del mes: el nodo HTTP que va despues
// hace una sola peticion, en vez de una por cada item que le llega.
